public void initFromGUPMarginComponentPriceAdjustmentLine(GUPMarginComponentPriceAdjustmentLine _gupMarginComponentPriceAdjustmentLine)
{
    this.OfferId                                = _gupMarginComponentPriceAdjustmentLine.OfferId;
    this.Description                            = _gupMarginComponentPriceAdjustmentLine.Description;
    this.DiscountPercentOrValue                 = _gupMarginComponentPriceAdjustmentLine.DiscountPercentOrValue;
    this.InstanceRelationType                   = _gupMarginComponentPriceAdjustmentLine.InstanceRelationType;
    this.IsDiscountCodeRequired                 = _gupMarginComponentPriceAdjustmentLine.IsDiscountCodeRequired;
    this.LineNum                                = GUPMarginComponentPriceAdjustmentLine::lastLineNum(_gupMarginComponentPriceAdjustmentLine.OfferId) + 1;
    this.Name                                   = _gupMarginComponentPriceAdjustmentLine.Name;
    this.UnitOfMeasure                          = _gupMarginComponentPriceAdjustmentLine.UnitOfMeasure;
    this.LineType                               = _gupMarginComponentPriceAdjustmentLine.LineType;
    this.IsDiscountApplyingLine                 = _gupMarginComponentPriceAdjustmentLine.IsDiscountApplyingLine;
    this.CalculateMethod                        = _gupMarginComponentPriceAdjustmentLine.CalculateMethod;
    this.UnitAppliesToAll                       = _gupMarginComponentPriceAdjustmentLine.UnitAppliesToAll;
    this.RetailGroupMemberLine                  = RetailGroupMemberLine::createRetailGroupMemberV2();
    this.InventDimId                            = _gupMarginComponentPriceAdjustmentLine.InventDimId;
    this.PriceAttributeGroupCombinationRecId    = _gupMarginComponentPriceAdjustmentLine.PriceAttributeGroupCombinationRecId;
    this.LinePricingGroupCode                   = _gupMarginComponentPriceAdjustmentLine.LinePricingGroupCode;
}

static LineNum lastLineNum(RetailDiscountOfferId _offerId)
{
    return (select maxof(LineNum) from GUPMarginComponentPriceAdjustmentLine
        where GUPMarginComponentPriceAdjustmentLine.OfferId == _offerId).LineNum;
}

    public void delete()
    {
        ttsbegin;

        if (FeatureStateProvider::isFeatureEnabled(GUPGlobalEnableFeature::instance()))
        {
            GUPPricingRule::find(this.LinePricingRule, true).delete();
        }

        super();

        ttscommit;
    }

    public display GUPPriceAttributeGroupPriority displayCombinationPriceAttributeGroupPriority()
    {
        GUPPriceComponentCodePriceAttributeGroupCombination priceAttributeGroupCombination;

        select firstonly Priority from priceAttributeGroupCombination
            where priceAttributeGroupCombination.RecId == this.PriceAttributeGroupCombinationRecId;

        return priceAttributeGroupCombination.Priority;
    }

    private boolean checkIfPriceAdjustmentHasHeaderPriceAttribute(RetailDiscountOfferId _offerId)
    {
        GUPMarginComponentPriceAdjustment marginComponentPriceAdjustment;
        select firstonly HeaderPricingRule from marginComponentPriceAdjustment
            where marginComponentPriceAdjustment.OfferId == _offerId;

        if (!marginComponentPriceAdjustment.HeaderPricingRule)
        {
            return checkFailed("@GlobalUnifiedPricing:GUPSetHeaderPriceAttributeGroupErrorMessage");
        }
        else
        {
            return true;
        }
    }
